package policyset
import("strings";"testing")
func TestResolvePreservesFloorAndAdditions(t *testing.T){o:=Policy{SchemaVersion:"1.0.0",Revision:"o",Commands:[]Command{{ID:"test",Executable:"go",Required:true}}};r:=Policy{SchemaVersion:"1.0.0",Revision:"r",Commands:[]Command{{ID:"lint",Executable:"lint",Required:true}}};got,err:=Resolve(o,r);if err!=nil||len(got.Commands)!=2||len(got.Delta)!=1{t.Fatalf("%+v %v",got,err)}}
func TestResolveRejectsDuplicateAndNonWaivableWeakening(t *testing.T){o:=Policy{SchemaVersion:"1.0.0",Revision:"o",Commands:[]Command{{ID:"test",Executable:"go",Required:true,NonWaivable:true}}};r:=Policy{SchemaVersion:"1.0.0",Revision:"r",Commands:[]Command{{ID:"test",Executable:"go"},{ID:"test",Executable:"go"}}};if _,err:=Resolve(o,r);err==nil||!strings.Contains(err.Error(),"non-waivable"){t.Fatalf("%v",err)}}
func TestResolveAllowsTypedException(t *testing.T){o:=Policy{SchemaVersion:"1.0.0",Revision:"o",Commands:[]Command{{ID:"test",Executable:"go",Required:true}}};r:=Policy{SchemaVersion:"1.0.0",Revision:"r",Commands:[]Command{{ID:"test",Executable:"go"}},Exceptions:[]Exception{{CommandID:"test",Approver:"owner",Rationale:"temporary",ExpiresAt:"2026-09-01"}}};if _,err:=Resolve(o,r);err!=nil{t.Fatal(err)}}
func TestResolveRejectsDuplicateRepositoryIDs(t *testing.T){o:=Policy{SchemaVersion:"1.0.0",Revision:"o"};r:=Policy{SchemaVersion:"1.0.0",Revision:"r",Commands:[]Command{{ID:"x",Executable:"go"},{ID:"x",Executable:"go"}}};if _,err:=Resolve(o,r);err==nil||!strings.Contains(err.Error(),"duplicate"){t.Fatalf("%v",err)}}
